for op, i, n, p, ts in sorted(changes, key=lambda c: c[4]):
    cur = db.execute('select updated_at from users where id=?', (i,)).fetchone()
    if cur and cur[0] > ts:
        continue  # 더 새 값이 이미 있으면 버린다
    if op == 'D':
        db.execute('delete from users where id=?', (i,))
    else:
        db.execute('insert into users values(?,?,?,?) on conflict(id) do update set name=excluded.name, plan=excluded.plan, updated_at=excluded.updated_at', (i, n, p, ts))
